std::wstring developerDate(const json& value){try{SYSTEMTIME utc{},local{};if(value.is_number()){ULARGE_INTEGER ticks{};ticks.QuadPart=uint64_t(value.get<double>()*10000000)+116444736000000000ULL;FILETIME file{ticks.LowPart,ticks.HighPart};if(!FileTimeToSystemTime(&file,&utc))return L"미기록";}else{auto t=value.is_string()?value.get<std::string>():"";if(t.size()<19)return wide(t.empty()?"미기록":t);utc.wYear=std::stoi(t.substr(0,4));utc.wMonth=std::stoi(t.substr(5,2));utc.wDay=std::stoi(t.substr(8,2));utc.wHour=std::stoi(t.substr(11,2));utc.wMinute=std::stoi(t.substr(14,2));utc.wSecond=std::stoi(t.substr(17,2));}if(!SystemTimeToTzSpecificLocalTime(nullptr,&utc,&local))return L"미기록";wchar_t out[40];swprintf(out,40,L"%04u-%02u-%02u %02u:%02u",local.wYear,local.wMonth,local.wDay,local.wHour,local.wMinute);return out;}catch(...){return L"미기록";}}
